+      titleTemplate: prefs['taskTracker.prTitleTemplate'] || '',
+      bodyTemplate: prefs['taskTracker.prBodyTemplate'] || '',
+      defaultBranch: prefs['taskTracker.prDefaultBranch'] || 'develop',
