+<script lang="ts">
+  import { Plus, Trash2 } from '@lucide/svelte'
+
+  interface ConfigEntry {
+    name: string
+    command: string
+    args?: string
+    cwd?: string
+    max_instances?: number
+    env?: Record<string, string>
+    pre_run?: string
+    post_run?: string
+  }
+
+  let {
+    config,
+    isNew = false,
