+      this.deps.windowManager.trackPtySession(senderId, session.id)
+      this.runningProcesses.set(session.id, {
+        sessionId: session.id,
+        name: payload.name,
+        configDir: resolvedConfigDir,
+        worktreePath: worktreeRoot,
+      })
