+
+      try {
+        const wsUrl = await this.deps.wsBridge.create(session.id, session.pty)
+        return { sessionId: session.id, wsUrl, running: this.listRunning(sender) }
+      } catch (error) {
+        cleanup()
+        this.deps.ptyManager.kill(session.id)
