+      }
+    } finally {
+      if (reserved) this.decrementInstance(instanceKey)
+    }
+  }
+
+  listRunning(sender?: WebContents): RunConfigProcessSnapshot[] {
+    const snapshots = Array.from(this.runningProcesses.values())
