+      )
+      if (!shared) {
+        try {
+          await window.api.keychainDeleteCredentials(tracker.provider, tracker.baseUrl)
+        } catch {
+          // best-effort cleanup
+        }
+      }
+    }
+
+    const updated = $state.snapshot(globalCfg) as typeof globalCfg
