+                <Check size={12} />
+                {#if creds.username}<span class="text-text-muted max-w-24 truncate"
+                    >{creds.username}</span
+                  >{/if}
+              </span>
+            {:else}
+              <span class="text-2xs text-warning-text shrink-0">No credentials</span>
